"""Same independently generated byte-exact inputs for all three validators."""
import base64
import gzip
import hashlib
import json
from pathlib import Path
import sys

import pytest

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'magnolie-organizer/bin'))
import magnolie_personal_sync as personal
import magnolie_personal_actor as actor

CASES = json.loads((ROOT / 'magnolie-notes/app/src/test/resources/personal-sync-batch-boundaries.json').read_text())['cases']


def test_windows_standalone_and_notes_use_identical_boundary_vectors():
    assert (ROOT / 'magnolie-organizer-windows/tests/resources/personal-sync-batch-boundaries.json').read_bytes() == (
        ROOT / 'magnolie-notes/app/src/test/resources/personal-sync-batch-boundaries.json').read_bytes()


@pytest.mark.parametrize('case', CASES, ids=lambda case: case['name'])
def test_shared_byte_exact_batch_boundary_and_actor_envelope(case):
    raw = gzip.decompress(base64.b64decode(case['gzip_base64'], validate=True))
    assert len(raw) == case['body_bytes'] and hashlib.sha256(raw).hexdigest() == case['sha256']
    body = json.loads(raw)
    assert personal.canonical(body) == raw
    for record in body['records']:
        assert personal.validate_record(record, body['format']) is record
    if body['format'] >= 2:
        assert personal.projection_hash(body['records']) == body['records_hash']
    if case['valid']:
        assert personal.validate_body('personal_sync.batch', body) is body
        envelope = actor.wrap(body['run_id'], 'personal_sync.batch', body)
        assert actor.unwrap(envelope) == ('personal_sync.batch', body)
        assert len(personal.canonical(envelope)) < personal.MAX_PACKET
    else:
        with pytest.raises(ValueError):
            personal.validate_body('personal_sync.batch', body)
        with pytest.raises(ValueError):
            actor.wrap(body['run_id'], 'personal_sync.batch', body)
